package com.moscilez.track.tracking;
import android.app.*; import android.content.*; import android.location.Location; import android.os.*; import androidx.annotation.Nullable; import androidx.core.app.NotificationCompat; import com.google.android.gms.location.*; import com.moscilez.track.data.*; import com.moscilez.track.domain.TrackMetrics; import java.util.*;
public class TrackingService extends Service {
 private ActivitySession session; private FusedLocationProviderClient client; private MTrackDatabase db; private LocationCallback callback; private final List<ActivityPoint> points=new ArrayList<>();
 @Override public void onCreate(){super.onCreate();db=MTrackDatabase.get(this);client=LocationServices.getFusedLocationProviderClient(this);String channel="tracking";if(Build.VERSION.SDK_INT>=26)((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(new NotificationChannel(channel,"MTrack tracking",NotificationManager.IMPORTANCE_LOW));startForeground(7,new NotificationCompat.Builder(this,channel).setContentTitle("MTrack recording").setContentText("Activity tracking is active").setSmallIcon(android.R.drawable.ic_menu_mylocation).build());}
 @Override public int onStartCommand(Intent i,int flags,int id){if(session!=null)return START_STICKY;session=new ActivitySession(i.getStringExtra("mode"),System.currentTimeMillis());session.id=db.sessions().insert(session);try{LocationRequest r=new LocationRequest.Builder(Priority.PRIORITY_HIGH_ACCURACY,5000).setMinUpdateDistanceMeters(5).build();callback=new LocationCallback(){@Override public void onLocationResult(LocationResult result){for(Location l:result.getLocations()){TrackMetrics.addPoint(points,l,session.id);db.points().insert(points.get(points.size()-1));session.distanceMeters=TrackMetrics.distance(points);session.maxSpeed=TrackMetrics.maxSpeed(points);session.avgSpeed=TrackMetrics.averageSpeed(points);db.sessions().update(session);}}};client.requestLocationUpdates(r,callback,Looper.getMainLooper());}catch(SecurityException ignored){}return START_STICKY;}
 @Override public void onDestroy(){if(callback!=null)client.removeLocationUpdates(callback);if(session!=null){session.endedAt=System.currentTimeMillis();session.durationMs=session.endedAt-session.startedAt;db.sessions().update(session);}super.onDestroy();}
 @Nullable @Override public android.os.IBinder onBind(Intent i){return null;}
}
